Here's a simple C++ program that finds the nth Fibonacci number using recursion:

```c++
#include <iostream>
using namespace std;

int fibonacci_recursion(int n) {
    if (n == 0 || n == 1) return 0;
    return fibonacci_recursion(n-1) + fibonacci_recursion(n-2);
}

int main() {
    int n;
    cout << "Enter the number: ";
    cin >> n;
    cout << "The nth Fibonacci number is: " << fibonacci_recursion(n) << endl;
    return 0;
}
```

