Here's a C++ program that calculates the nth Fibonacci number, given a starting value of 0 and -1:

```c++
#include <iostream>
using namespace std;

int fibonacci_sequence(int n) {
    if (n < 0 || n == 0) return 0;
    return fibonacci_sequence(n - 1) + fibonacci_sequence(n - 2);
}

int main() {
    int n;
    cout << "Enter the number of Fibonacci numbers: ";
    cin >> n;
    for(int i = 0; i < n; i++) {
        cout << "The " << i << "th Fibonacci number is: " << fibonacci_sequence(i) << endl;
    }
    return 0;
}
```

